// Explicit own single-block CT driver hooks; no upstream numerical method changes.
extern void X3ICTBeginStage(MeshBlock*,int,Real,Real);
extern void X3ICTFluxAudit(MeshBlock*,int,Real);
extern void X3ICTBoundaryEMF(MeshBlock*,int,Real,Real);

TaskStatus TimeIntegratorTaskList::CalculateHydroFlux(MeshBlock *pmb, int stage) {
  Hydro *phydro = pmb->phydro;
  Field *pfield = pmb->pfield;

  if (stage <= nstages) {
    if (stage_wghts[stage-1].main_stage) {
      if (integrator != "rk2") throw std::runtime_error("x3i_ct requires SSPRK2");
      X3ICTBeginStage(pmb, stage, pmb->pmy_mesh->time + (stage == 2 ? pmb->pmy_mesh->dt : 0), pmb->pmy_mesh->dt);
      if ((integrator == "vl2") && (stage-stage_wghts[0].orbital_stage == 1)) {
        phydro->CalculateFluxes(phydro->w,  pfield->b,  pfield->bcc, 1);
      } else {
        phydro->CalculateFluxes(phydro->w,  pfield->b,  pfield->bcc, pmb->precon->xorder);
      }
      X3ICTFluxAudit(pmb, stage, pmb->pmy_mesh->dt);
    }
    return TaskStatus::next;
  }
  return TaskStatus::fail;
}

